/**
 * @rovqix/areas — the area-page generator and the subdomain registry.
 *
 * One subdomain per business type, each with a clear purpose and a keyword
 * name: plumber-websites.rovqix.in, dental-practice-websites.rovqix.in, …
 * Each publishes 14 page variants x 1,107 cities = 15,498 pages, inside
 * Cloudflare's 20,000-file limit. Each subdomain is its own app in
 * apps/<id>/, generated by scripts/create-area-apps.mjs.
 */
import { variants } from "./variants";
import type { Shard, Track } from "./generator";
import { serviceTypes } from "./service-type-list";

export * from "./generator";
export { variants, type Variant } from "./variants";
export { serviceTypes };
export type { ServiceType } from "./service-types";
export type { City } from "./cities";

/**
 * Business types that do not get their own site. Cloudflare allows 100
 * projects per account: rovqix.in + 99 trade sites. photographer-studio
 * duplicates photographer; notary-service and travel-agent have the weakest
 * local search demand.
 */
const WITHOUT_SITE = new Set(["photographer-studio", "notary-service", "travel-agent"]);

/** Subdomain (and app folder) for a business type: plumber -> plumber-websites */
export function siteIdFor(serviceSlug: string): string {
  return `${serviceSlug}-websites`;
}

/** Every area subdomain, in order. */
export const shards: Shard[] = serviceTypes
  .filter((service) => !WITHOUT_SITE.has(service.slug))
  .map((service) => ({
    id: siteIdFor(service.slug),
    subdomain: siteIdFor(service.slug),
    tracks: variants.map((variant): Track => ({ service, variant })),
  }));

export function getShard(id: string): Shard | undefined {
  return shards.find((shard) => shard.id === id);
}

/** The subdomain and track a business type + variant is published on. */
export function findTrack(serviceSlug: string, variantSlug: string): { shard: Shard; track: Track } | undefined {
  for (const shard of shards) {
    const track = shard.tracks.find((t) => t.service.slug === serviceSlug && t.variant.slug === variantSlug);
    if (track) return { shard, track };
  }
  return undefined;
}

/**
 * The subdomain being built, from the AREA_SHARD environment variable that
 * each Cloudflare Pages project sets. Fails the build loudly when missing.
 */
export function getCurrentShard(): Shard {
  const id = process.env.AREA_SHARD;
  // `next dev` without AREA_SHARD previews the first subdomain. Production
  // builds must name one, so a misconfigured Cloudflare project fails loudly.
  if (!id && process.env.NODE_ENV !== "production") return shards[0];
  const shard = id ? getShard(id) : undefined;
  if (!shard) {
    throw new Error(`AREA_SHARD must name a site such as ${shards[0].id} (got ${JSON.stringify(id)}).`);
  }
  return shard;
}
